<?php use App\Executives\{AppointmentService,PositionService,LifecycleService};$closed=$appointment['ended_on']||$appointment['cancelled_at'];$scheduled=$appointment['starts_on']>gmdate('Y-m-d'); ?>
<div class="page-heading"><div><a class="back-link" href="<?= e(url('executive_appointments',['organization_scope'=>\App\Executives\OrganizationService::code($appointment),'state'=>$appointment['cancelled_at']?'cancelled':($appointment['ended_on']?'ended':'all_open')])) ?>">Back to appointments</a><span class="section-kicker d-block mt-2">APPOINTMENT #<?= e($appointment['id']) ?></span><h1><?= e($appointment['position_name_snapshot']) ?></h1><p><?= e($appointment['member_name_snapshot']) ?> · <?= e(PositionService::LEVELS[$appointment['organization_level']]) ?></p></div><div class="d-flex flex-wrap gap-2"><?php if($appointment['member_id']): ?><a class="btn btn-outline-primary" href="<?= e(url('member',['id'=>$appointment['member_id']])) ?>">Open member profile</a><?php endif; ?><?php if(\App\Auth::canManage()&&!$closed): ?><a class="btn btn-primary" href="<?= e(url('executive_appointment_manage',['id'=>$appointment['id']])) ?>"><?= $scheduled?'Manage / cancel reservation':'End / manage service' ?></a><?php endif; ?></div></div>
<?php if($closed): ?><div class="alert alert-secondary"><?= $appointment['cancelled_at']?'Cancelled reservation — no completed service term.':'This service term has ended. Its original details are retained as read-only history.' ?></div><?php endif; ?>
