<?php $details=['Organization'=>\App\Executives\OrganizationService::label($appointment),'Wing enrollment reference'=>($appointment['wing_enrollment_id']??null)?'#'.$appointment['wing_enrollment_id']:'Not applicable','Position at appointment'=>$appointment['position_name_snapshot'],'Member at appointment'=>$appointment['member_name_snapshot'],'Party ID at appointment'=>$appointment['party_id_snapshot']??'Not recorded','Sys No. at appointment'=>$appointment['member_number_snapshot'],'Jurisdiction at appointment'=>$appointment['jurisdiction_snapshot'],'Appointment type'=>AppointmentService::TYPES[$appointment['appointment_type']],'Start date'=>date_display($appointment['starts_on']),'Expected end date'=>$appointment['expected_ends_on']?date_display($appointment['expected_ends_on']):'Not set','State'=>$appointment['cancelled_at']?'Cancelled — not served':($appointment['ended_on']?'Ended':($scheduled?'Scheduled':'Current')),'Recorded by'=>$appointment['created_by']??'Not recorded','Recorded (UTC)'=>date_display($appointment['created_at'],true)];if($appointment['ended_on']){$details['Actual last day of service']=date_display($appointment['ended_on']);$details['End reason']=LifecycleService::REASONS[$appointment['end_reason']]??$appointment['end_reason'];}if($appointment['cancelled_at']){$details['Cancelled (UTC)']=date_display($appointment['cancelled_at'],true);}if($closed){$details['Closed by']=$appointment['closed_by']??'Not recorded';}foreach($details as $label=>$value): ?><dt class="col-md-4 py-2 fw-normal text-secondary"><?= e($label) ?></dt><dd class="col-md-8 py-2"><?= e($value) ?></dd><?php endforeach; ?></dl>
<?php if($appointment['replaces_appointment_id']): ?><p><a href="<?= e(url('executive_appointment',['id'=>$appointment['replaces_appointment_id']])) ?>">View previous term #<?= e($appointment['replaces_appointment_id']) ?></a></p><?php endif; ?><?php if($appointment['successor_id']): ?><p><a href="<?= e(url('executive_appointment',['id'=>$appointment['successor_id']])) ?>">View successor term #<?= e($appointment['successor_id']) ?></a></p><?php endif; ?>
<?php if($appointment['is_deceased']): ?><div class="alert alert-secondary">This person is marked deceased. Their appointment records are retained.</div><?php endif; ?>
<h2 class="h6">Appointment notes</h2><p class="text-break" style="white-space:pre-wrap"><?= e($appointment['notes']??'No notes recorded.') ?></p>
<?php if($closed): ?><h2 class="h6"><?= $appointment['cancelled_at']?'Cancellation notes':'End notes' ?></h2><p class="text-break" style="white-space:pre-wrap"><?= e($appointment['end_notes']??'No notes recorded.') ?></p><?php endif; ?>
<p class="small text-secondary mb-0">Names, IDs and jurisdiction are preserved as recorded when appointed. Ending service does not remove membership or change life status.</p></div></section>
